import { toast } from "sonner";
import { api, errorMessage } from "@/lib/api";
import type { ExpenseFilters } from "@/types/expense";
import { dateKey } from "@/utils/date";

/** Downloads the ledger (optionally filtered) as a CSV generated by the server. */
export async function exportExpensesToCSV(filters: ExpenseFilters = {}): Promise<void> {
  try {
    const { data } = await api.get<Blob>("/expenses/export.csv", {
      params: Object.fromEntries(Object.entries(filters).filter(([, v]) => v)),
      responseType: "blob",
    });
    const url = URL.createObjectURL(data);
    const link = document.createElement("a");
    link.href = url;
    link.download = `expenses-${dateKey(new Date())}.csv`;
    document.body.appendChild(link);
    link.click();
    link.remove();
    URL.revokeObjectURL(url);
    toast.success("Ledger exported as CSV.");
  } catch (error) {
    toast.error(errorMessage(error, "Export failed."));
  }
}
